import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, Vector2 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    imageUrl,
    scenePosition,
    sceneRotation,
    sceneScale,
    interactions,
    cinematicPrimitives,
    atlasRegion,
    atlas
  } = config;

  // Load texture
  const texture = ctx.textureLoader.load(imageUrl);

  // Handle atlas region: offset and repeat
  if (atlasRegion && atlas !== undefined) {
    const sourceRect = atlasRegion;
    const atlasSize = new Vector2(512, 320); // Assumed from spec; adjust if needed
    texture.repeat.set(
      sourceRect.width / atlasSize.x,
      sourceRect.height / atlasSize.y
    );
    texture.offset.set(
      sourceRect.x / atlasSize.x,
      1 - (sourceRect.y + sourceRect.height) / atlasSize.y
    );
  }

  // Plane geometry with aspect ratio
  const img = texture.image;
  const aspect = img ? img.width / img.height : 1.6;
  const width = aspect > 1 ? aspect : 1;
  const height = aspect > 1 ? 1 : 1 / aspect;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new Mesh(geometry, material);

  // Transform
  mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  mesh.rotation.set(sceneRotation.x, sceneRotation.y, sceneRotation.z);
  mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // Handlers container
  mesh.userData.handlers = {};
  let hoverTween = null;

  // Hover: rise-in
  const hoverPreset = interactions?.find(i => i.event === 'hover')?.effect;
  const riseDelta = hoverPreset?.includes('0.15') ? 0.15 : 0.15;
  mesh.userData.handlers.pointerover = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: mesh.position.y + riseDelta,
      duration: 0.7,
      ease: 'power3.out'
    });
  };
  mesh.userData.handlers.pointerout = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: scenePosition.y,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click: press-down and emit
  mesh.userData.handlers.click = () => {
    // Press-down scale animation
    gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(mesh.scale, {
          x: sceneScale.x,
          y: sceneScale.y,
          duration: 0.12,
          ease: 'back.out'
        });
      }
    });
    // Emit event – parent is expected to listen on the object or use ctx.emit
    if (ctx.emit) ctx.emit('hub-pricing.select');
  };

  // Apply cinematic primitives
  if (cinematicPrimitives) {
    cinematicPrimitives.forEach(primitive => {
      const fn = ctx.primitives[primitive.name];
      if (fn) fn(mesh, primitive.params);
    });
  }

  // Cleanup
  mesh.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    texture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
